// The `catalog` tool (design 6.2): on-demand documentation, generated by @glimpse/catalog from the same definitions
// the compiler validates against.
import {
  CALC_NAMES, calcDoc, calcName, componentDoc, componentIndex, COMPONENT_BY_NAME, examplesDoc, parseViewRef, SOURCE_BY_NAME, sourceDoc, sourceIndex, VIEW_BY_NAME, VIEW_INDEX, viewDoc,
} from '@glimpse/catalog';
import {closeMatch, nearest} from '../spec/errors.ts';
import {refSignature} from '../spec/expand.ts';
import type {SourceRegistry} from '../sources/registry.ts';
import {failed, text, type ToolResult} from './result.ts';

export const CATALOG_DESCRIPTION =
  'Look up Glimpse details. names: components ("DataTable"), sources ("git.churn"), presets ("view:diff", returns the preset\'s Express source), "grammar" (full Express reference) or "examples". No names: the index.';

export const CATALOG_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {names: {type: 'array', items: {type: 'string'}}},
} as const;

const MAX_NAMES = 12;
/**
 * The `grammar` topic: A2UI Express as Glimpse accepts it, and nothing else. The upstream prompt's rules (3,900
 * characters) describe surfaces, client functions, checks and templates that a Glimpse spec never uses, and say
 * strings are double-quoted only. test/mcp/tools.test.ts compiles one example per rule below.
 */
export const GRAMMAR = [
  '## Grammar Rules (A2UI Express, as Glimpse accepts it)',
  "1. A spec is statements, one per line or separated by ';'. No <a2ui> tags and no surface(...) line: the id argument of show selects the view.",
  "2. root=Page('Title',[...]) starts a view, or replaces the layout of an existing one and keeps its data.",
  "3. name=Comp(...) defines a named part. Use the bare name as a child: root=Page('T',[intro,table]). Sending name=Comp(...) again later patches just that part; a new part nobody refers to is appended to root.",
  "4. Arguments are positional in signature order, then name=value. _ skips an optional positional: Grid([a,b],_,'m'). Children are a list of names or nested calls: [intro, Text('x')].",
  "5. Values: 'single' or \"double\" quoted strings (an apostrophe inside single quotes is fine: 'doesn't'; \\n is a line break), numbers, true, false, null, [lists] and {key: value} objects.",
  "6. $/path=value sets data: $/plan=[{title:'A',status:'done'}], then $/plan/0/status='doing'. $/path as an argument binds to it: Steps($/plan). /ds and /meta belong to the server.",
  "7. A data argument is a source ref string ('git.churn src top=20'), a $/path or inline data. Refs run locally and are never sent to you.",
  '8. # or // starts a comment. Text that is not a statement is ignored and reported; a spec cut off mid-call has its brackets closed and says so.',
  "9. add|sub|mul|div(a, b) compute from numbers, $/paths or calls, in any argument and inline rows: Stat(div($/w/seats,60)). Slider('Seats',$/w/seats) edits $/w/seats and calls reading it update. No operators ($/a*2 is mul($/a,2)); no calls inside $/data.",
].join('\n');

function index(): string {
  return [`Views: ${VIEW_INDEX}`, 'Components (? optional):', componentIndex(), `Sources: ${sourceIndex()}`,
    'catalog{names:[...]} for details: a component, a function ("div"), a source, "view:<name>", "grammar" or "examples".'].join('\n');
}

const viewNames = (): string[] => [...VIEW_BY_NAME.keys(), 'gallery'];

/** Every name the tool answers, for fuzzy matching. */
function vocabulary(registry: SourceRegistry | undefined): string[] {
  return [...COMPONENT_BY_NAME.keys(), ...CALC_NAMES, ...new Set([...SOURCE_BY_NAME.keys(), ...(registry?.keys() ?? [])]), ...viewNames().map(name => `view:${name}`), 'grammar', 'examples'];
}

function lookup(name: string, registry: SourceRegistry | undefined): string | undefined {
  if (name === 'grammar') return GRAMMAR;
  if (name === 'examples') return examplesDoc();
  if (COMPONENT_BY_NAME.has(name)) return componentDoc(name);
  // Decision D25: the four functions, by name or alias, in any case ('div', 'Div', 'multiply').
  if (calcName(name) !== undefined) return calcDoc();
  if (SOURCE_BY_NAME.has(name)) return sourceDoc(name);
  const extra = registry?.get(name);
  if (extra) return `${refSignature(extra.meta)} -> ${extra.meta.kind} (${extra.meta.shape}, max ${extra.meta.budget}) - ${extra.meta.doc}`;
  const call = name.startsWith('view:') ? name.slice(5).trim() : viewNames().includes(name.split(/\s+/)[0] ?? '') ? name : undefined;
  if (call !== undefined) {
    const {view, target, args} = parseViewRef(call);
    return viewDoc(view, target, args);
  }
  return undefined;
}

/** `registry` adds sources the catalog does not list (none in production); undefined before the services are loaded. */
export async function catalogTool(args: {names?: unknown}, registry: SourceRegistry | undefined): Promise<ToolResult> {
  const names = Array.isArray(args.names) ? args.names.filter((name): name is string => typeof name === 'string' && name.trim() !== '').map(name => name.trim()) : [];
  if (names.length === 0) return text(index());

  const blocks: string[] = [];
  let found = 0;
  for (const name of [...new Set(names)].slice(0, MAX_NAMES)) {
    let doc = lookup(name, registry);
    if (doc === undefined) {
      const words = vocabulary(registry);
      // A bare or misspelt name: try the closest catalog name, with and without the view: prefix.
      const guess = closeMatch(name, words) ?? closeMatch(`view:${name}`, words);
      doc = guess ? lookup(guess, registry) : undefined;
      if (doc !== undefined) doc = `"${name}" -> ${guess}\n${doc}`;
    }
    if (doc === undefined) blocks.push(`unknown "${name.slice(0, 60)}". Nearest: ${nearest(name, vocabulary(registry)).join(' ')}`);
    else { blocks.push(doc); found++; }
  }
  if (names.length > MAX_NAMES) blocks.push(`(${names.length - MAX_NAMES} more names ignored: ask for at most ${MAX_NAMES} at a time)`);
  const body = blocks.join('\n\n');
  return found === 0 ? failed(`${body}\n\n${index()}`) : text(body);
}
